import { Controller, Ip } from "@nestjs/common";
import { TypedRoute, TypedBody } from "@nestia/core";
import typia from "typia";
import { postTodoAuthUserJoin } from "../../../../providers/postTodoAuthUserJoin";
import { postTodoAuthUserLogin } from "../../../../providers/postTodoAuthUserLogin";
import { postTodoAuthUserRefresh } from "../../../../providers/postTodoAuthUserRefresh";

import { ITodoUser } from "../../../../api/structures/ITodoUser";

@Controller("/todo/auth/user")
export class TodoAuthUserController {
  /**
   * Performs user registration by creating a new account with the provided
   * credentials.
   *
   * This operation validates the email format and password strength. If the
   * email is already registered, it returns a 409 Conflict response.
   *
   * The system stores encrypted password in the database using bcrypt
   * algorithm, sets email_verified_at to null, and creates a pending
   * verification entry in the email verification table.
   *
   * After successful creation, the user is required to verify their email
   * before using the service. The registration process does not allow the user
   * to set a display name at signup - that is part of user profile management.
   *
   * The response includes the newly created user identifier and a verification
   * token for email verification flow.
   *
   * @param connection
   * @param body User registration information including email and password.
   * @setHeader token.access Authorization
   *
   * @x-autobe-specification User registration process. Creates a new user account, hashes the password, stores in database, and sets email verification status to pending. Generates a random verification token and stores it in todo_user_email_verifications. Sends verification email through email service.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: ITodoUser.IJoin,
  ): Promise<ITodoUser.IAuthorized> {
    try {
      return await postTodoAuthUserJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
